export default function MenuCard({
  item,
  quantity = 0,
  addToCart,
  removeFromCart
}) {
  const outOfStock = item.stock <= 0;

  return (
    <div className={`menu-card ${outOfStock ? "out" : ""}`}>
      {/* Badges */}
      <div className="badges">
        {item.is_top_rated && <span className="badge top">⭐ Top Rated</span>}
        {item.is_popular && <span className="badge hot">🔥 Popular</span>}
      </div>

      <h3>{item.name}</h3>
      <p className="price">₹{item.price}</p>

      <div className="rating">
        ⭐ {item.avg_rating || 0} | Sold: {item.total_sold || 0}
      </div>

      <div className="stock">Stock: {item.stock}</div>

      {/* Controls */}
      {outOfStock ? (
        <button className="btn-disabled" disabled>
          Unavailable
        </button>
      ) : quantity === 0 ? (
        <button className="btn-add" onClick={() => addToCart(item)}>
          ADD
        </button>
      ) : (
        <div className="qty-box">
          <button onClick={() => removeFromCart(item.id)}>−</button>
          <span>{quantity}</span>
          <button onClick={() => addToCart(item)}>+</button>
        </div>
      )}
    </div>
  );
}
